/* HARDGATE — build stamp. Single source of truth for "which version am I running?"
   Loaded FIRST so every later script can read G.HG_BUILD. */
(function(){
'use strict';
var G = (typeof window !== 'undefined') ? window : globalThis;

var HG_BUILD = {
  version: 'hg-v952',
  pack: 'THE COVERAGE REPORTER REPORTED WHAT ITS AUTHOR TYPED. hg-v949 built it so gaps would name themselves and hg-v951 fixed its first blind spot, but EVERY via string in it was a claim nothing ever checked - hg-v946 hand-typed-prefer-book failure living inside the reporter built to stop gaps hiding. Two things followed. FIRST: SUPER GOLD was listed covered via its own weekend read. It DOES read the calendar - and it read it on Date.now() at ALL FOUR of its sites rather than on the signal bar. The veto is real, it pushes a reason and stands the candidate down, so the error ran in BOTH directions: a setup formed on a Friday and reviewed on a Saturday was vetoed for a closure it never met, and one formed on a Saturday and reviewed on a Monday sailed through. hg-v949 wrote the rule that a Monday re-run over Friday bars must give Friday answer into the shared formation while this desk did the opposite, and the reporter called it covered because the string said so. Driven end to end through the REAL audit, both cases now flip, and the wall clock is used only when a candidate carries no instant at all - with the reason SAYING so, so the two are distinguishable. SECOND: TAURIC was absent from the list ENTIRELY, a second blind spot one pack after the first was fixed. It prices XAUUSD and writes entry, stop and t1 to the forward log, and had no weekend reference of any kind. It is listed and wired now, and deliberately MARKS rather than withholds: those rows already record ticket false and gateClear false, so there is no ticket to withhold - what was missing is the mark, without which a future measurement of this desk cannot separate the tradeable rows from the rest, which is exactly how NEW GOLD record came to be half weekend. THE REPORTER NOW CALLS EACH ROUTE with a known Saturday and a known Wednesday and requires it to tell them apart. VERIFIED means it was called and did. BROKEN means it was called and could not - a route that never fires, one that always fires and one that throws all read broken, because a stuck rule is not a calendar. CLAIMED means there is nothing callable to test, so the via string is an author claim and is LABELLED one rather than counted as coverage. The buckets still partition the list and covered still holds every routed desk, so existing readers are unchanged. TWO ARGUMENT SHAPES, because the desks genuinely differ: a desk whose setups carry their own instant takes a number, one whose setups carry none reads the last closed bar of a SERIES. The first cut of the probe called every route with a number and reported GOLD PINE and GOLD PRO broken - a FALSE ALARM FROM THE REPORTER, not a defect in them - and the guard reproduces that false alarm so the shape cannot be dropped again. WHERE IT STANDS with the desks loaded: OPTI GOLD, GOLD PINE, GOLD PRO, 80PERCENT and TAURIC VERIFIED; OMNIGOLD CLAIMED, because its hg-v420 veto is real but not independently callable, and that is reported as a claim rather than as proof. TWO SURVIVORS THE MUTATION PASS FOUND IN MY OWN GUARD: the instant reader test used only ABSENT keys, which coerce to NaN and are caught by any finiteness check, so a reader that read null as 1970 survived - it is now driven with explicit null, empty string and zero; and the TAURIC mark was asserted only through its verdict function, never through the real record path, so deleting the mark survived - the real hgTauricRecord is now driven and the written row read back. No gate, threshold or verdict moves on any other desk, and no setup leaves any board. Tests: tests/test-gold-weekend-verified.mjs, 47 assertions, 14 of 14 behavioural mutations caught across gold-formation.js, super-gold.js and tauric.js with the baseline verified green first',
  built: '2026-09-24T00:00:00Z'
};

function hgBuildLabel(b){
  b = b || HG_BUILD;
  var v = String(b.version || '').replace(/^hg-/, '');
  var p = b.pack ? ' · ' + b.pack : '';
  return v ? v + p : 'unknown build';
}

function hgBuildParseVersion(text){
  try{
    if (typeof text !== 'string' || !text) return null;
    var m = text.match(/version\s*:\s*['"]([A-Za-z0-9._-]{1,64})['"]/);
    return m ? m[1] : null;
  }catch(e){ return null; }
}

function hgBuildCompare(loaded, live){
  if (!loaded || !live) return { state: 'unknown', reason: 'could not read one side' };
  if (String(loaded) === String(live)) return { state: 'fresh', reason: 'matches server' };
  return { state: 'stale', reason: 'server is on ' + live + ', this tab loaded ' + loaded };
}

function hgBuildDistance(loaded, live){
  try{
    var a = String(loaded || '').match(/(\d+)\s*$/);
    var b = String(live || '').match(/(\d+)\s*$/);
    if (!a || !b) return null;
    return (+b[1]) - (+a[1]);
  }catch(e){ return null; }
}

function hgBuildChipState(res, b){
  b = b || HG_BUILD;
  var label = hgBuildLabel(b);
  if (!res || res.state === 'pending') return { text: label, cls: 'ok', title: 'checking for newer build' };
  if (res.state === 'fresh') return { text: label, cls: 'ok', title: 'running current build (' + res.live + ')' };
  if (res.state === 'stale'){
    var d = hgBuildDistance(res.loaded, res.live);
    var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
    return { text: label + ' · STALE' + behind, cls: 'bad', title: res.reason + ' — hard-reload to pick it up' };
  }
  return { text: label + ' · ?', cls: 'warn', title: (res.reason || 'freshness unknown') + ' — offline or blocked' };
}

function hgBuildFreshness(fetchImpl){
  var f = (typeof fetchImpl === 'function') ? fetchImpl : (typeof G.fetch === 'function' ? G.fetch.bind(G) : null);
  var loaded = HG_BUILD.version;
  if (!f) return Promise.resolve({ state: 'unknown', loaded: loaded, live: null, reason: 'no fetch' });
  var url = './build-stamp.js?fresh=' + Date.now();
  return f(url, { cache: 'no-store' }).then(function(res){
    if (!res || !res.ok) throw new Error('http ' + (res && res.status));
    return res.text();
  }).then(function(text){
    var live = hgBuildParseVersion(text);
    var cmp = hgBuildCompare(loaded, live);
    return { state: cmp.state, loaded: loaded, live: live, reason: cmp.reason };
  }).catch(function(e){
    return { state: 'unknown', loaded: loaded, live: null, reason: (e && e.message) || 'network failed' };
  });
}

function hgBuildSwWaiting(){
  try{
    var sw = G.navigator && G.navigator.serviceWorker;
    if (!sw || !sw.controller) return Promise.resolve(false);
    return sw.getRegistration().then(function(reg){
      return !!(reg && reg.waiting);
    }).catch(function(){ return false; });
  }catch(e){ return Promise.resolve(false); }
}

function hgRenderBuildChip(el, res){
  try{
    var node = el || (G.document && G.document.getElementById('chipBuild'));
    if (!node) return null;
    var st = hgBuildChipState(res);
    node.textContent = '';
    var b = G.document.createElement('b');
    b.textContent = st.text;
    node.appendChild(b);
    node.title = st.title;
    node.className = 'statuschip hg-build-' + st.cls;
    return st;
  }catch(e){ return null; }
}

function hgRenderVerBadge(res){
  try{
    var node = G.document && G.document.getElementById('hgVerBadge');
    if (!node) return null;
    var v = String(HG_BUILD.version || '').replace(/^hg-/, '');
    if (!v){ node.style.display = 'none'; return null; }
    if (res && res.state === 'stale'){
      var d = hgBuildDistance(res.loaded, res.live);
      var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
      node.textContent = v + ' · STALE' + behind;
      node.className = 'verbadge verbadge-stale';
      node.title = (res.reason || 'stale') + ' — reloading…';
      return { stale: true };
    }
    node.textContent = v;
    node.className = 'verbadge';
    node.title = HG_BUILD.version + (HG_BUILD.pack ? (' · ' + HG_BUILD.pack) : '');
    return { stale: false };
  }catch(e){ return null; }
}

function hgBuildMaybeReload(res, storage, reloadFn){
  try{
    if (!res || res.state !== 'stale' || !res.live) return false;
    var store = storage;
    if (!store && G.sessionStorage) store = G.sessionStorage;
    if (!store || typeof store.getItem !== 'function') return false;
    var key = 'hg_build_reload_' + String(res.live);
    if (store.getItem(key)) return false;
    var reload = reloadFn;
    if (!reload && G.location && typeof G.location.reload === 'function') reload = G.location.reload.bind(G.location);
    if (typeof reload !== 'function') return false;
    store.setItem(key, '1');
    reload();
    return true;
  }catch(e){}
  return false;
}

function hgBuildApplyFreshness(res){
  try{
    if (!res) return res;
    hgRenderBuildChip(null, res);
    hgRenderVerBadge(res);
    G.HG_BUILD_FRESHNESS = res;
    hgBuildMaybeReload(res);
    return res;
  }catch(e){ return res; }
}

function hgBuildInit(){
  try{
    hgRenderBuildChip(null, null);
    hgRenderVerBadge(null);
    hgBuildFreshness().then(function(res){
      return hgBuildSwWaiting().then(function(waiting){
        if (waiting && res.state === 'fresh'){
          res = { state: 'stale', loaded: res.loaded, live: res.live, reason: 'new build downloaded' };
        }
        return hgBuildApplyFreshness(res);
      });
    });
    if (G.document && typeof G.document.addEventListener === 'function'){
      G.document.addEventListener('visibilitychange', function(){
        try{
          if (!G.document || G.document.visibilityState !== 'visible') return;
          hgBuildFreshness().then(hgBuildApplyFreshness);
        }catch(e){}
      });
    }
  }catch(e){}
}

G.HG_BUILD = HG_BUILD;
G.hgBuildLabel = hgBuildLabel;
G.hgBuildParseVersion = hgBuildParseVersion;
G.hgBuildCompare = hgBuildCompare;
G.hgBuildDistance = hgBuildDistance;
G.hgBuildChipState = hgBuildChipState;
G.hgBuildFreshness = hgBuildFreshness;
G.hgBuildSwWaiting = hgBuildSwWaiting;
G.hgRenderBuildChip = hgRenderBuildChip;
G.hgRenderVerBadge = hgRenderVerBadge;
G.hgBuildMaybeReload = hgBuildMaybeReload;
G.hgBuildApplyFreshness = hgBuildApplyFreshness;
G.hgBuildInit = hgBuildInit;

try{
  if (G.document){
    if (G.document.readyState === 'loading'){
      G.document.addEventListener('DOMContentLoaded', hgBuildInit);
    } else {
      hgBuildInit();
    }
  }
}catch(e){}

})();
